MP="py -3.13 <your-picture-maker>/make-picture.py"
STY="Black and white colouring-book page, simple whiteboard marker line art: only black marker lines on a pure white background, uncoloured, every area left white, one clean uniform thick black outline weight, friendly simple doodle, very few details, no shading, no hatching, no dots, no grey, no text, the object centred with a wide white margin around it."
NEG="colour, colored, coloured fill, brown, orange, yellow, green, red, lettuce, tomato, cheese, ham, shading, hatching, cross-hatching, stippling, grey tones, gradient, photo, realistic, 3d render, text, letters, words, numbers, watermark, logo, signature, blurry, low quality, sketchy messy lines, thin lines, frame, border"
O=assets_work/wb
$MP "$STY Subject: one slice of sandwich bread seen from above at a slight angle, its top covered in a smooth layer of peanut butter drawn as an outlined area just inside the crust, a butter knife lying across it spreading the peanut butter, three or four curved swoosh lines on the spread for texture." $O/spread --n 4 --seed 311 --negative "$NEG"
$MP "$STY Subject: a whole peanut butter sandwich, two slices of bread stacked on top of each other, seen at a slight three-quarter angle from above, between the slices one smooth even thin band of peanut butter filling shows along the edge, no vegetables." $O/stack --n 4 --seed 411 --negative "$NEG"
$MP "$STY Subject: a whole square peanut butter sandwich lying on a rectangular cutting board seen from above at a slight angle, a big kitchen knife with its blade laid along the diagonal of the sandwich, cutting it from the top-left corner to the bottom-right corner." $O/cut --n 4 --seed 511 --negative "$NEG"
$MP "$STY Subject: two triangle peanut butter sandwich halves on a round plate, slightly apart from each other, on each cut edge one smooth even band of peanut butter filling shows between the two bread layers, no vegetables." $O/halves --n 4 --seed 611 --negative "$NEG"
